function main(p, state) {
  const cells = p.cells || [];
  const c = state.container || {};
  const slots = c.slots || [];
  const RESULT = 0;
  const GRID_FIRST = 1;
  const GRID_LAST = 9;
  const PLAYER_FROM = 10;

  const bySlot = {};
  for (let i = 0; i < slots.length; i++) {
    const s = slots[i];
    if (s && typeof s.slot === 'number' && s.id) bySlot[s.slot] = s;
  }

  function matcher(spec) {
    if (spec === 'planks') return function (id) { return /^minecraft:[a-z_]+_planks$/.test(id); };
    if (spec === 'stick') return function (id) { return /^minecraft:stick$/.test(id); };
    if (spec === 'log') return function (id) {
      return /^minecraft:(stripped_)?[a-z_]+(_log|_wood|_stem|_hyphae)$/.test(id) || /^minecraft:(stripped_)?bamboo_block$/.test(id);
    };
    return function (id) { return id === spec; };
  }

  const errors = [];
  const pending = [];
  const wanted = {};
  for (let i = 0; i < cells.length; i++) {
    const cell = cells[i];
    if (!cell || typeof cell.slot !== 'number') continue;
    wanted[cell.slot] = true;
    const m = matcher(cell.match);
    const existing = bySlot[cell.slot];
    if (existing) {
      if (m(existing.id)) continue;
      errors.push('grid slot ' + cell.slot + ' already holds ' + existing.id);
    } else {
      pending.push(cell);
    }
  }

  for (let g = GRID_FIRST; g <= GRID_LAST; g++) {
    if (wanted[g]) continue;
    if (bySlot[g]) errors.push('grid slot ' + g + ' should be empty but holds ' + bySlot[g].id);
  }

  const sources = [];
  for (let i = 0; i < slots.length; i++) {
    const s = slots[i];
    if (!s || !s.id || typeof s.slot !== 'number') continue;
    if (s.slot < PLAYER_FROM) continue;
    sources.push({ slot: s.slot, id: s.id, left: s.count || 0 });
  }
  sources.sort(function (a, b) { return a.slot - b.slot; });

  const use = {};
  const order = [];
  const missing = [];
  for (let i = 0; i < pending.length; i++) {
    const cell = pending[i];
    const m = matcher(cell.match);
    let found = null;
    for (let k = 0; k < sources.length; k++) {
      if (sources[k].left > 0 && m(sources[k].id)) { found = sources[k]; break; }
    }
    if (!found) { missing.push(cell.slot); continue; }
    found.left = found.left - 1;
    if (!use[found.slot]) { use[found.slot] = []; order.push(found.slot); }
    use[found.slot].push(cell.slot);
  }

  order.sort(function (a, b) { return a - b; });
  const clicks = [];
  for (let i = 0; i < order.length; i++) {
    const src = order[i];
    clicks.push({ slot: src, button: 0, clickType: 0 });
    const targets = use[src];
    for (let k = 0; k < targets.length; k++) {
      clicks.push({ slot: targets[k], button: 1, clickType: 0 });
    }
    clicks.push({ slot: src, button: 0, clickType: 0 });
  }

  const ok = errors.length === 0 && missing.length === 0;
  const reason = errors.slice();
  for (let i = 0; i < missing.length; i++) {
    reason.push('no matching item in player slots for grid slot ' + missing[i]);
  }
  if (!ok) {
    return { clicks: [], ok: false, reason: reason.join('; '), missing: missing };
  }
  clicks.push({ slot: RESULT, button: 0, clickType: 1 });
  return { clicks: clicks, ok: true, reason: '', missing: [] };
}
